"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[769],{396:function(n){n.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-08-final-project</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="a08a9536" class="cell markdown">\n<h1 id="лабораторная-работа--8-итоговый-проект-комплексное-решение-задачи">Лабораторная\nработа № 8. Итоговый проект: комплексное решение задачи</h1>\n<p><strong>Курс:</strong> Классическое машинное обучение, 4 курс\nприкладной математики</p>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Применить все полученные знания к решению реальной задачи — от\nразведочного анализа до интерпретации итоговой модели.</p>\n<p><strong>Используемые инструменты:</strong> Все изученные\nбиблиотеки.</p>\n</div>\n<div id="726181be" class="cell markdown">\n<h3 id="регламент-сдачи">Регламент сдачи</h3>\n<p>Работа сдаётся в виде <strong>этого ноутбука</strong>, дополненного\nвашим решением, и <strong>краткой презентации на 3–5 слайдов</strong>\nдля защиты.</p>\n<p><strong>Критерии оценки проекта:</strong></p>\n<table>\n<thead>\n<tr>\n<th>Критерий</th>\n<th>Вес</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Глубина анализа данных</td>\n<td>20 %</td>\n</tr>\n<tr>\n<td>Качество предобработки</td>\n<td>15 %</td>\n</tr>\n<tr>\n<td>Разнообразие моделей и обоснованность выбора</td>\n<td>25 %</td>\n</tr>\n<tr>\n<td>Качество финального решения на тестовой выборке</td>\n<td>20 %</td>\n</tr>\n<tr>\n<td>Интерпретация и выводы</td>\n<td>20 %</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p>Итоговый проект отличается от предыдущих работ тем, что\n<strong>готового скелета нет</strong>: структуру решения вы выстраиваете\nсами. Ниже — только контрольные точки.</p>\n</blockquote>\n</div>\n<div id="d474a364" class="cell markdown">\n<h2 id="шаг-0-выбор-датасета">Шаг 0. Выбор датасета</h2>\n<p>Возьмите любой открытый датасет: Titanic, House Prices, Heart Disease\nс Kaggle, данные UCI или свои. Требования: не менее 500 объектов и не\nменее 8 признаков, среди которых есть категориальные.</p>\n<p><strong>Заполните карточку проекта:</strong></p>\n<ul>\n<li><strong>Датасет:</strong> …</li>\n<li><strong>Ссылка:</strong> …</li>\n<li><strong>Задача:</strong> классификация / регрессия</li>\n<li><strong>Целевая переменная:</strong> …</li>\n<li><strong>Число объектов / признаков:</strong> …</li>\n<li><strong>Метрика качества и почему именно она:</strong> …</li>\n</ul>\n</div>\n<div id="f7aa3e55" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> seaborn <span class="im">as</span> sns</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="op">%</span>matplotlib inline</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="dv">7</span>, <span class="dv">4</span>),</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a>sns.set_palette(<span class="st">&quot;viridis&quot;</span>)</span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span></span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: загрузите данные и выведите первые строки</span></span></code></pre></div>\n</div>\n<div id="10393fc3" class="cell markdown">\n<h2 id="шаг-1-разведочный-анализ">Шаг 1. Разведочный анализ</h2>\n<p>Минимум: описательные статистики, анализ пропусков, распределения\nпризнаков, матрица корреляций, зависимость целевой переменной от\nключевых признаков.</p>\n</div>\n<div id="e704505f" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: EDA</span></span></code></pre></div>\n</div>\n<div id="f797b945" class="cell markdown">\n<p><strong>Выводы по EDA:</strong> <em>что вы узнали о данных? Есть ли\nдисбаланс классов, выбросы, утечки?</em></p>\n</div>\n<div id="c2c49231" class="cell markdown">\n<h2 id="шаг-2-предобработка">Шаг 2. Предобработка</h2>\n<p>Пропуски, кодирование категориальных признаков, масштабирование. Всё\nоформите пайплайном — иначе на шаге 4 будет утечка данных.</p>\n</div>\n<div id="9aaee19b" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: ColumnTransformer + Pipeline</span></span></code></pre></div>\n</div>\n<div id="cbd5e84e" class="cell markdown">\n<h2 id="шаг-3-обучение-моделей">Шаг 3. Обучение моделей</h2>\n<p>Минимум <strong>три разных типа</strong> моделей, например:</p>\n<ol>\n<li>линейная (логистическая регрессия / Ridge);</li>\n<li>метрическая или ядровая (kNN / SVM);</li>\n<li>ансамблевая (случайный лес / градиентный бустинг).</li>\n</ol>\n<p>Обязательно добавьте <strong>baseline</strong>\n(<code>DummyClassifier</code> или предсказание константой) — без него\nнепонятно, хороши ли ваши 0.85 accuracy.</p>\n</div>\n<div id="5db2f24c" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: обучите модели, сведите результаты в таблицу</span></span></code></pre></div>\n</div>\n<div id="64345b13" class="cell markdown">\n<h2 id="шаг-4-подбор-гиперпараметров">Шаг 4. Подбор гиперпараметров</h2>\n<p>Кросс-валидация + GridSearch или RandomizedSearch для каждой\nмодели.</p>\n</div>\n<div id="1a5411e4" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: подбор гиперпараметров</span></span></code></pre></div>\n</div>\n<div id="d8035feb" class="cell markdown">\n<h2 id="шаг-5-сравнение-моделей">Шаг 5. Сравнение моделей</h2>\n<p>Таблица: модель | параметры | метрика на CV | метрика на тесте |\nвремя обучения. Добавьте графическое сравнение (ROC-кривые всех моделей\nна одном графике или boxplot по фолдам).</p>\n</div>\n<div id="61ec3b86" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сравнение</span></span></code></pre></div>\n</div>\n<div id="259fb1a3" class="cell markdown">\n<h2 id="шаг-6-интерпретация-лучшей-модели">Шаг 6. Интерпретация лучшей\nмодели</h2>\n<p>SHAP или важность признаков + анализ ошибок: посмотрите на объекты,\nгде модель ошиблась сильнее всего. Есть ли у них что-то общее?</p>\n</div>\n<div id="21f10883" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: интерпретация</span></span></code></pre></div>\n</div>\n<div id="fbad44f9" class="cell markdown">\n<h2 id="шаг-7-итоговый-вывод">Шаг 7. Итоговый вывод</h2>\n<p><em>Напишите развёрнутый вывод (10–15 предложений):</em></p>\n<ol>\n<li>Какую задачу решали и на каких данных.</li>\n<li>Какая модель победила и с каким результатом (в числах, с\nдоверительным интервалом по фолдам).</li>\n<li>Почему победила именно она — что в структуре данных этому\nспособствовало.</li>\n<li>Какие признаки оказались самыми информативными и согласуется ли это\nсо здравым смыслом.</li>\n<li>Где модель ошибается и что с этим можно сделать.</li>\n<li>Что вы сделали бы дальше, будь у вас больше данных или времени.</li>\n</ol>\n<h2 id="подготовка-к-защите">Подготовка к защите</h2>\n<p>Соберите презентацию на 3–5 слайдов:</p>\n<ol>\n<li>Задача и данные.</li>\n<li>Ключевые находки EDA (1–2 графика).</li>\n<li>Сравнение моделей (таблица или график).</li>\n<li>Интерпретация лучшей модели.</li>\n<li>Выводы.</li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);